using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Loads more topics in a channel direct messages chat administered by the current user. The loaded topics will be sent through updateDirectMessagesChatTopic.
    /// Topics are sorted by their topic.order in descending order. Returns a 404 error if all topics have been loaded
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> LoadDirectMessagesChatTopicsAsync(long chatId = default, int limit = default)
    {

           using var activity =  StartCallActivity("LoadDirectMessagesChatTopicsAsync", typeof(LoadDirectMessagesChatTopics).FullName ?? "LoadDirectMessagesChatTopicsAsync");

           try
           {
             return client.LoadDirectMessagesChatTopicsAsync(chatId, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
